import ee, math
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
pt = ee.Geometry.Point([-77.944710, 34.225726])  # Wilmington, NC
start, end = '2018-01-01', '2019-01-01'

def safe_get(val):
    try:
        return val.getInfo()
    except Exception:
        return None

def compute_total_mm(col_id, band, start, end, region, scale, mult=1.0):
    col = (ee.ImageCollection(col_id)
           .filterDate(start, end)
           .filterBounds(region))
    size = safe_get(col.size())
    if size is None:
        return {'ok': False, 'err': 'fetch_failed'}
    if size == 0:
        return {'ok': False, 'size': 0}
    sum_img = col.select(band).sum().multiply(mult).rename('precip')
    count = safe_get(sum_img.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=region,
        scale=scale,
        maxPixels=1e9,
    ).get('precip'))
    if count is None:
        return {'ok': False, 'err': 'count_failed', 'size': size}
    if int(count) == 0:
        return {'ok': False, 'size': size, 'count': 0}
    mean_val = safe_get(sum_img.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=region,
        scale=scale,
        maxPixels=1e9,
    ).get('precip'))
    return {'ok': True, 'size': size, 'count': int(count), 'mm': mean_val}

# 2. Try CHIRPS with robust region/scale, then fallback/expand if needed
attempts = [
    ('CHIRPS', 'UCSB-CHG/CHIRPS/DAILY', 'precipitation', pt.buffer(10000).bounds(), 2500, 1.0),
    ('CHIRPS', 'UCSB-CHG/CHIRPS/DAILY', 'precipitation', pt.buffer(30000).bounds(), 3000, 1.0),
    ('ERA5-Land', 'ECMWF/ERA5_LAND/DAILY_AGGR', 'total_precipitation_sum', pt.buffer(10000).bounds(), 2500, 1000.0),
    ('ERA5-Land', 'ECMWF/ERA5_LAND/DAILY_AGGR', 'total_precipitation_sum', pt.buffer(30000).bounds(), 3000, 1000.0),
]

result = None
source = None
for src, col_id, band, region, scale, mult in attempts:
    out = compute_total_mm(col_id, band, start, end, region, scale, mult)
    if out.get('ok'):
        result = out
        source = src
        break
    # If collection truly empty on first source, try fallback; if all attempts empty -> C1
    # If count == 0, continue to next attempt
    continue

# 3. Decide outcomes
if result is None:
    # Determine if it was empty collections vs valid but no pixels
    # Re-check a simple size for both to classify C1 vs C2
    chirps_size = safe_get(ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY').filterDate(start, end).filterBounds(pt.buffer(30000)).size())
    era_size = safe_get(ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR').filterDate(start, end).filterBounds(pt.buffer(30000)).size())
    if (chirps_size == 0 or chirps_size is None) and (era_size == 0 or era_size is None):
        print("2018 Images: 0")
        print("C1")
    else:
        print("Valid Pixels: 0")
        print("C2")
else:
    total_mm = result['mm']
    if (total_mm is None) or (isinstance(total_mm, float) and (math.isnan(total_mm) or total_mm < 0 or total_mm > 10000)):
        print(f"Source: {source}")
        print(f"2018 Images: {result['size']}")
        print(f"Valid Pixels: {result['count']}")
        print("C3")
    else:
        inches = total_mm / 25.4
        print(f"Source: {source}")
        print(f"2018 Images: {result['size']}")
        print(f"Valid Pixels: {result['count']}")
        print(f"Total 2018 Precipitation: {total_mm:.2f} mm ({inches:.2f} in)")
        if inches >= 90.0:
            print("A")
        else:
            print("B")
